package com.xpertsedge.hrms;
import java.util.*;import java.time.Instant;import java.security.*;import java.nio.*;import javax.crypto.*;import javax.crypto.spec.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MailMfa {
 private final MailSecurityRepo records;private final byte[] key;private final SecureRandom random=new SecureRandom();
 public MailMfa(MailSecurityRepo records,JwtService jwt){this.records=records;this.key=jwt.mailEncryptionKey();}
 static final String ABC="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
 static String base32(byte[] bytes){StringBuilder out=new StringBuilder();int bits=0,value=0;for(byte b:bytes){value=(value<<8)|(b&255);bits+=8;while(bits>=5){out.append(ABC.charAt((value>>(bits-5))&31));bits-=5;}}if(bits>0)out.append(ABC.charAt((value<<(5-bits))&31));return out.toString();}
 static byte[] decode(String s){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int value=0,bits=0;for(char c:s.toCharArray()){int n=ABC.indexOf(c);if(n<0)throw new IllegalArgumentException();value=(value<<5)|n;bits+=5;if(bits>=8){out.write((value>>(bits-8))&255);bits-=8;}}return out.toByteArray();}
 static String code(String secret,long counter){try{Mac mac=Mac.getInstance("HmacSHA1");mac.init(new SecretKeySpec(decode(secret),"HmacSHA1"));byte[] hash=mac.doFinal(ByteBuffer.allocate(8).putLong(counter).array());int off=hash[19]&15;int n=ByteBuffer.wrap(hash,off,4).getInt()&0x7fffffff;return String.format(Locale.ROOT,"%06d",n%1000000);}catch(Exception e){throw new IllegalStateException(e);}}
 String crypt(String value,boolean encrypt){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");byte[] all=encrypt?null:Base64.getDecoder().decode(value),nonce=new byte[12];if(encrypt)random.nextBytes(nonce);else System.arraycopy(all,0,nonce,0,12);c.init(encrypt?Cipher.ENCRYPT_MODE:Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));if(!encrypt)return new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),java.nio.charset.StandardCharsets.UTF_8);byte[] data=c.doFinal(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(ByteBuffer.allocate(12+data.length).put(nonce).put(data).array());}catch(Exception e){throw new IllegalStateException("Cannot access authenticator secret.");}}
 MailSecurity record(Long id){return records.findByOwnerId(id).orElseGet(()->{MailSecurity m=new MailSecurity();m.ownerId=id;return m;});}
 @Transactional public boolean enabled(Long id){return record(id).enabled;}
 @Transactional public String setup(Long id){MailSecurity m=record(id);if(m.enabled)throw WebmailController.bad("Disable existing 2FA before setting up another authenticator.");byte[] bytes=new byte[20];random.nextBytes(bytes);String secret=base32(bytes);m.pendingCipher=crypt(secret,true);m.pendingExpires=Instant.now().plusSeconds(300);records.save(m);return secret;}
 long validCounter(String secret,String supplied,long last){if(supplied==null||!supplied.matches("[0-9]{6}"))return -1;long now=Instant.now().getEpochSecond()/30;for(long t=now-1;t<=now+1;t++)if(t>last&&MessageDigest.isEqual(code(secret,t).getBytes(),supplied.getBytes()))return t;return -1;}
 @Transactional public List<String> confirm(Long id,String supplied){MailSecurity m=record(id);if(m.pendingCipher==null||m.pendingExpires==null||!m.pendingExpires.isAfter(Instant.now()))throw WebmailController.bad("Setup expired. Start again.");long counter=validCounter(crypt(m.pendingCipher,false),supplied,-1);if(counter<0)throw WebmailController.bad("Invalid authenticator code.");m.enabled=true;m.secretCipher=m.pendingCipher;m.pendingCipher=null;m.pendingExpires=null;m.lastCounter=counter;List<String> codes=new ArrayList<>();for(int i=0;i<8;i++){byte[] bytes=new byte[12];random.nextBytes(bytes);codes.add(HexFormat.of().formatHex(bytes));}m.recoveryHashes=String.join("\n",codes.stream().map(WebmailAuth::fingerprint).toList());records.save(m);return codes;}
 @Transactional public boolean verify(Long id,String supplied){MailSecurity m=record(id);if(!m.enabled)return true;if(supplied==null)return false;long counter=validCounter(crypt(m.secretCipher,false),supplied,m.lastCounter);if(counter>=0){m.lastCounter=counter;records.save(m);return true;}List<String> hashes=new ArrayList<>(Arrays.asList(m.recoveryHashes.split("\n")));boolean found=hashes.remove(WebmailAuth.fingerprint(supplied.trim().toLowerCase(Locale.ROOT)));if(found){m.recoveryHashes=String.join("\n",hashes);records.save(m);}return found;}
 @Transactional public void disable(Long id,String supplied){if(!verify(id,supplied))throw WebmailController.bad("Invalid authenticator or recovery code.");MailSecurity m=record(id);m.enabled=false;m.secretCipher=null;m.pendingCipher=null;m.pendingExpires=null;m.recoveryHashes="";m.lastCounter=-1;records.save(m);}
}
